gnature_payload: &amp;Hash&lt;32&gt;, signatures: &amp;Vec&lt;Signature&gt;,) -&gt; Result&lt;(), AccError&gt; { for i in 0..signatures.len() { let signature = signatures.get_unchecked(i); if i &gt; 0 { let prev_signature = signatures.get_unchecked(i - 1); if prev_signature.public_key &gt;= signature.public_key { return Err(AccError::BadSignatureOrder); } } if !env .storage() .instance() .has(&amp;DataKey::Signer(signature.public_key.clone())) { return Err(AccError::UnknownSigner); } env.crypto().ed25519_verify( &amp;signature.public_key, &amp;signature_payload.clone().into(), &amp;signature.signature, ); } Ok(())}fn verify_authorization_policy( env: &amp;Env, context: &amp;Context, curr_contract: &amp;Address, all_signed: bool,) -&gt; Result&lt;(), AccError&gt; { let contract_context = match context { Context::Contract(c) =&gt; { if &amp;c.contract == curr_contract { if !all_signed { return Err(AccError::NotEnoughSigners); } } c } Context::CreateContractHostFn(_) =&gt; return Err(AccError::InvalidContext), Context::CreateContractWithCtorHostFn(_) =&gt; return Err(AccError::InvalidContext), }; if contract_context.fn_name != TRANSFER_FN &amp;&amp; contract_context.fn_name != Symbol::new(env, "approve") { return Ok(()); } let current_time = env.ledger().timestamp(); let time_limit: Option&lt;u64&gt; = env.storage() .instance() .get::&lt;_, u64&gt;(&amp;DataKey::TimeLimit(contract_context.contract.clone())); if let Some(limit) = time_limit { let last_transfer_time: u64 = env.storage() .instance() .get::&lt;_, u64&gt;(&amp;DataKey::LastTransferTime(contract_context.contract.clone())) .unwrap_or(0); if current_time - last_transfer_time &lt; limit { return Err(AccError::TimeLimitExceeded); } env.storage() .instance() .set(&amp;DataKey::LastTransferTime(contract_context.contract.clone()), &amp;current_time); } Ok(())}mod test;
